#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int EDAT;
    int CT = 0, SUM = 0, Q50 = 0;
    int ME = 0, QME = 0;

    cin >> EDAT;                      // lectura avançada
    while (EDAT != 0) {
        CT++;                         // comptador
        SUM = SUM + EDAT;             // acumulador
        if (EDAT >= 50) {
            Q50++;                    // comptador amb condició
        }
        if (EDAT > ME) {              // nou màxim
            ME = EDAT;
            QME = 1;
        } else if (EDAT == ME) {      // es repeteix el màxim
            QME++;
        }
        cin >> EDAT;                  // la següent, al final del cos
    }

    double MIT = (double) SUM / CT;   // divisió real
    cout << fixed << setprecision(2);
    cout << "La mitjana d'edat es " << MIT << endl;
    cout << "Persones mes grans o iguals a 50 anys " << Q50 << endl;
    cout << "L'edat del mes gran es " << ME << endl;
    cout << "L'han tingut " << QME << " persones" << endl;
    return 0;
}

