#include <iostream>
using namespace std;

int main() {
    int dorsal;
    int jove = 0, mitjana = 0, avancada = 0, mega = 0;

    cin >> dorsal;
    while (dorsal != -1) {
        if (dorsal <= 3999) {
            jove++;
        } else if (dorsal <= 4999) {
            mitjana++;
        } else if (dorsal <= 5999) {
            avancada++;
        } else {
            mega++;
        }
        cin >> dorsal;
    }

    int maxim = jove;                         // màxim de quatre valors
    if (mitjana > maxim) maxim = mitjana;
    if (avancada > maxim) maxim = avancada;
    if (mega > maxim) maxim = mega;

    cout << "Categoria/es amb mes participants:";
    if (jove == maxim) cout << " jove";       // totes les que empaten
    if (mitjana == maxim) cout << " mitjana";
    if (avancada == maxim) cout << " avancada";
    if (mega == maxim) cout << " mega";
    cout << endl;
    return 0;
}

